create schema if not exists app;
create schema if not exists part2;
create schema if not exists report;
revoke all on schema app,part2,report from public,anon,authenticated;
grant usage on schema app to authenticated,service_role;
grant usage on schema part2,report to service_role;
alter default privileges in schema app revoke execute on functions from public;
alter default privileges in schema part2 revoke all on tables from public,anon,authenticated;
alter default privileges in schema report revoke all on tables from public,anon,authenticated;
create function app.touch_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create function app.immutable_row() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'immutable_record'; end $$;
create table public.orgs(id uuid primary key default gen_random_uuid(),org_id uuid not null unique,code text not null unique,name text not null,synthetic boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint org_self foreign key(org_id) references public.orgs(id) deferrable initially deferred);
grant select on public.orgs to authenticated; grant all on public.orgs to service_role; alter table public.orgs enable row level security;
create table public.sites(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),code text not null,name text not null,timezone text not null default 'America/Los_Angeles',synthetic boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,id),unique(org_id,code));
grant select on public.sites to authenticated; grant all on public.sites to service_role; alter table public.sites enable row level security;
create table public.locations(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),site_id uuid not null,code text not null,name text not null,synthetic boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,site_id) references public.sites(org_id,id),unique(org_id,id),unique(org_id,code));
grant select on public.locations to authenticated; grant all on public.locations to service_role; alter table public.locations enable row level security;
create table public.programs(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),site_id uuid not null,code text not null,name text not null,draft boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,site_id) references public.sites(org_id,id),unique(org_id,id),unique(org_id,code));
grant select on public.programs to authenticated; grant all on public.programs to service_role; alter table public.programs enable row level security;
create table public.county_programs(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),program_id uuid not null,county_code text not null,configuration jsonb not null default '{}',draft boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,program_id) references public.programs(org_id,id),unique(org_id,id));
grant select on public.county_programs to authenticated; grant all on public.county_programs to service_role; alter table public.county_programs enable row level security;
create table public.accounts(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),auth_user_id uuid unique references auth.users(id) on delete cascade,kind text not null check(kind in ('staff','patient','advocate')),synthetic boolean not null default true,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,id));
grant select on public.accounts to authenticated; grant all on public.accounts to service_role; alter table public.accounts enable row level security;
create table public.staff_members(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),account_id uuid unique,source_key text not null,name text not null,active boolean not null default true,synthetic boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,account_id) references public.accounts(org_id,id),unique(org_id,id),unique(org_id,source_key));
grant select on public.staff_members to authenticated; grant all on public.staff_members to service_role; alter table public.staff_members enable row level security;
create table public.staff_role_assignments(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),staff_member_id uuid not null,role text not null,is_primary boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,staff_member_id) references public.staff_members(org_id,id),unique(org_id,staff_member_id,role));
grant select on public.staff_role_assignments to authenticated; grant all on public.staff_role_assignments to service_role; alter table public.staff_role_assignments enable row level security;
create unique index one_primary_staff_role on public.staff_role_assignments(staff_member_id) where is_primary and active;
create table public.acting_role_sessions(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),account_id uuid not null,role text not null,ended_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,account_id) references public.accounts(org_id,id));
grant select on public.acting_role_sessions to authenticated; grant all on public.acting_role_sessions to service_role; alter table public.acting_role_sessions enable row level security;
create unique index one_acting_role on public.acting_role_sessions(account_id) where ended_at is null;
create table app.record_class_grants(id uuid primary key default gen_random_uuid(),org_id uuid references public.orgs(id),role text not null,record_class text not null,level text not null check(level in ('none','summary','read','write','consent_gated')),registry_version text not null default 'roles-oct27-44x18',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(role,record_class));
grant select on app.record_class_grants to authenticated; grant all on app.record_class_grants to service_role; alter table app.record_class_grants enable row level security;
create table public.feature_flags(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),flag_id text not null,enabled boolean not null default false,simulated boolean not null default false,mode text not null default 'off' check(mode in ('on','off','live')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,flag_id));
grant select on public.feature_flags to authenticated; grant all on public.feature_flags to service_role; alter table public.feature_flags enable row level security;
create table public.audit_events(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),actor_account_id uuid,actor_role text,action_code text not null,entity_id uuid,patient_id uuid,outcome text not null check(outcome in ('succeeded','blocked','simulated')),metadata jsonb not null default '{}',simulated boolean not null default false,registry_version text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,actor_account_id) references public.accounts(org_id,id));
grant select on public.audit_events to authenticated; grant select,insert on public.audit_events to service_role; revoke update,delete on public.audit_events from authenticated,anon,service_role; alter table public.audit_events enable row level security;
create table public.record_access_log(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),actor_account_id uuid not null,actor_role text,patient_id uuid not null,record_class text not null,kind text not null check(kind in ('open','section','print','export','brief','compute')),view_count integer not null default 1,last_viewed_at timestamptz not null default now(),simulated boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,actor_account_id) references public.accounts(org_id,id));
grant select on public.record_access_log to authenticated; grant select,insert,update on public.record_access_log to service_role; alter table public.record_access_log enable row level security;
create table public.patients(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),account_id uuid unique,source_key text not null,first_name text not null,last_name text not null,dob date,synthetic boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,account_id) references public.accounts(org_id,id),unique(org_id,id),unique(org_id,source_key));
grant select on public.patients to authenticated; grant all on public.patients to service_role; alter table public.patients enable row level security;
create table public.patient_contacts(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),patient_id uuid not null,kind text not null check(kind in ('email','phone','emergency')),value text not null,synthetic boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,patient_id) references public.patients(org_id,id),unique(org_id,id));
grant select on public.patient_contacts to authenticated; grant all on public.patient_contacts to service_role; alter table public.patient_contacts enable row level security;
alter table public.record_access_log add foreign key(org_id,patient_id) references public.patients(org_id,id);
alter table public.audit_events add foreign key(org_id,patient_id) references public.patients(org_id,id);
create table public.consent_versions(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),form_key text not null,version integer not null,content_en text not null,content_es text,spanish_review_status text not null default 'draft' check(spanish_review_status in ('draft','reviewed')),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),published boolean not null default false,counsel_draft boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,id),unique(org_id,form_key,version));
grant select on public.consent_versions to authenticated; grant select,insert on public.consent_versions to service_role; alter table public.consent_versions enable row level security;
create table public.consent_records(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),patient_id uuid not null,version_id uuid,consent_type text not null check(consent_type in ('part2_tpo_single','part2_specific_written','counseling_notes_release','hipaa_authorization','referrer_authorization','advocate_release','legal_part2_disclosure','po_voluntary_coordination','telehealth','group_confidentiality','ai_recording','sms_reminder','portal_reminder')),recipients jsonb not null default '[]',purpose_code text not null,items text[],status text not null check(status in ('active','revoked','superseded','expired','needs_review')),effective_at timestamptz not null,expires_at timestamptz,expires_on_event text,expiry_event_occurred_at timestamptz,supersedes_id uuid,signed_by_kind text not null check(signed_by_kind in ('patient','staff_capture','paper')),signature_method text not null check(signature_method in ('e_sign','wet_sign_upload','verbal_assent')),signed_at timestamptz not null,part2_elements jsonb not null default '{}',legacy_unverified boolean not null default false,needs_review_after_merge boolean not null default false,synthetic boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,patient_id) references public.patients(org_id,id),foreign key(org_id,version_id) references public.consent_versions(org_id,id),unique(org_id,id),foreign key(org_id,supersedes_id) references public.consent_records(org_id,id));
grant select on public.consent_records to authenticated; grant select,insert,update on public.consent_records to service_role; alter table public.consent_records enable row level security;
create table public.consent_signed_copies(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),consent_record_id uuid not null,storage_pointer text not null,sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),synthetic boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,consent_record_id) references public.consent_records(org_id,id),unique(org_id,id));
grant select on public.consent_signed_copies to authenticated; grant select,insert on public.consent_signed_copies to service_role; revoke update,delete on public.consent_signed_copies from authenticated,anon,service_role; alter table public.consent_signed_copies enable row level security;
create table public.disclosure_events(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),patient_id uuid not null,consent_record_id uuid not null,actor_account_id uuid,recipient_code text not null,purpose_code text not null,item_codes text[] not null default '{}',simulated boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,patient_id) references public.patients(org_id,id),foreign key(org_id,consent_record_id) references public.consent_records(org_id,id),foreign key(org_id,actor_account_id) references public.accounts(org_id,id));
grant select on public.disclosure_events to authenticated; grant select,insert on public.disclosure_events to service_role; alter table public.disclosure_events enable row level security;
create table public.tester_attestations(id uuid primary key default gen_random_uuid(),org_id uuid not null references public.orgs(id),account_id uuid not null,statement_version text not null default 'fictional-only-v1',language text not null check(language in ('en','es')),synthetic boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(org_id,account_id) references public.accounts(org_id,id),unique(org_id,account_id,statement_version));
grant select on public.tester_attestations to authenticated; grant select,insert on public.tester_attestations to service_role; alter table public.tester_attestations enable row level security;
create function app.account_id() returns uuid language sql stable security definer set search_path='' as $$ select id from public.accounts where auth_user_id=auth.uid() and active $$;
create function app.org_id() returns uuid language sql stable security definer set search_path='' as $$ select org_id from public.accounts where id=app.account_id() $$;
create function app.current_role() returns text language sql stable security definer set search_path='' as $$ select s.role from public.acting_role_sessions s join public.staff_members m on m.account_id=s.account_id and m.org_id=s.org_id join public.staff_role_assignments r on r.staff_member_id=m.id and r.org_id=m.org_id and r.role=s.role and r.active where s.account_id=app.account_id() and s.ended_at is null and m.active $$;
create function app.owns_patient(p_patient uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.patients where id=p_patient and account_id=app.account_id() and org_id=app.org_id()) $$;
/* Replaced invalid draft audit guard below with the concise guard after this comment.
create function app.pii_shape_guard() returns trigger language plpgsql set search_path='' as $$ declare k text; v jsonb; begin if new.action_code !~ '^[a-z][a-z0-9_.]{0,95}$' or new.registry_version !~ '^[a-zA-Z0-9_.-]{1,100}$' then raise exception 'audit_codes_only'; end if jsonb_typeof(new.metadata)<>'object' then raise exception 'audit_ids_only'; end if new.simulated and new.outcome='succeeded' then raise exception 'simulated_outcome_required'; end if length(new.metadata::text)>4096 then raise exception 'audit_metadata_limit'; end if new.actor_role is not null and new.actor_role !~ '^[a-z_]{1,48}$' then raise exception 'audit_role_code_only'; end if exists(select 1 from jsonb_each(new.metadata) e where e.key !~ '^[a-z_]+_(id|code)$' or jsonb_typeof(e.value)<>'string' or (e.key like '%_id' and trim(both '"' from e.value::text) !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$') or (e.key like '%_code' and trim(both '"' from e.value::text) !~ '^[a-z][a-z0-9_]{0,63}$')) then raise exception 'audit_ids_only'; end if new.metadata::text ~* '[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}' then raise exception 'audit_pii_rejected'; end if new.actor_account_id is not null and not exists(select 1 from public.accounts where id=new.actor_account_id and org_id=new.org_id) then raise exception 'audit_actor_org_mismatch'; end if new.patient_id is not null and not exists(select 1 from public.patients where id=new.patient_id and org_id=new.org_id) then raise exception 'audit_patient_org_mismatch'; end if new.created_at<>new.updated_at then raise exception 'audit_timestamp_mismatch'; end if new.actor_role is not null and new.actor_role !~ '^[a-z_]+$' then raise exception 'audit_pii_rejected'; end if new.action_code ~ '[0-9]{7}' then raise exception 'audit_pii_rejected'; end if new.registry_version ~ '[0-9]{7}' then raise exception 'audit_pii_rejected'; end if new.action_code ~ '^.*(name|email|phone|dob)\.' then raise exception 'audit_pii_rejected'; end if new.metadata ? 'name_code' or new.metadata ? 'email_code' or new.metadata ? 'phone_code' or new.metadata ? 'dob_code' then raise exception 'audit_pii_rejected'; end if new.actor_role is not null and new.actor_role='patient' and new.actor_account_id is null then raise exception 'audit_actor_required'; end if new.action_code='' then raise exception 'audit_code_required'; end if new.registry_version='' then raise exception 'audit_registry_required'; end if new.metadata::text ~ '[0-9]{3}[- .][0-9]{3}[- .][0-9]{4}' then raise exception 'audit_pii_rejected'; end if new.metadata::text ~ '[0-9]{4}-[0-9]{2}-[0-9]{2}' then raise exception 'audit_pii_rejected'; end if new.metadata::text ~ '"[^"]* [^"]*"' and new.metadata<>'{}'::jsonb then null; end if new.metadata::text ~ '[0-9]{10}' then raise exception 'audit_pii_rejected'; end if new.actor_role is not null and length(new.actor_role)>48 then raise exception 'audit_pii_rejected'; end if new.metadata::text ~ '\\u' then raise exception 'audit_encoding_rejected'; end if new.patient_id is not null and new.entity_id is null then null; end if new.metadata::text like '%<%' then raise exception 'audit_pii_rejected'; end if new.metadata::text like '%>%' then raise exception 'audit_pii_rejected'; end if new.registry_version like '%@%' then raise exception 'audit_pii_rejected'; end if new.action_code like '%@%' then raise exception 'audit_pii_rejected'; end if new.actor_role like '%@%' then raise exception 'audit_pii_rejected'; end if new.registry_version like '% %' then raise exception 'audit_pii_rejected'; end if new.action_code like '% %' then raise exception 'audit_pii_rejected'; end if new.actor_role like '% %' then raise exception 'audit_pii_rejected'; end if new.outcome not in ('succeeded','blocked','simulated') then raise exception 'audit_outcome_code'; end if new.created_at>now()+interval '1 minute' then raise exception 'audit_future_timestamp'; end if new.created_at<now()-interval '1 minute' then raise exception 'audit_backdated_timestamp'; end if new.metadata::text like '%\n%' then raise exception 'audit_pii_rejected'; end if new.metadata::text like '%\r%' then raise exception 'audit_pii_rejected'; end if new.metadata::text like '%\t%' then raise exception 'audit_pii_rejected'; end if new.actor_role is null and new.actor_account_id is not null then null; end if new.org_id is null then raise exception 'audit_org_required'; end if new.metadata is null then raise exception 'audit_metadata_required'; end if new.simulated is null then raise exception 'audit_simulated_required'; end if new.registry_version is null then raise exception 'audit_registry_required'; end if new.action_code is null then raise exception 'audit_action_required'; end if new.outcome is null then raise exception 'audit_outcome_required'; end if new.actor_account_id is not null and new.actor_role is not null and new.actor_role not in ('patient','advocate','system_migration') and not exists(select 1 from public.staff_members m join public.staff_role_assignments r on r.staff_member_id=m.id and r.org_id=m.org_id where m.account_id=new.actor_account_id and m.org_id=new.org_id and r.role=new.actor_role and r.active and m.active) then raise exception 'audit_unheld_role'; end if new.metadata::text ~ '"[^"]*@[^"]*"' then raise exception 'audit_pii_rejected'; end if new.metadata::text ~ '"[^"]*[+][0-9][^"]*"' then raise exception 'audit_pii_rejected'; end if new.registry_version ~ '[0-9]{4}-[0-9]{2}-[0-9]{2}' then raise exception 'audit_pii_rejected'; end if new.actor_role ~ '[0-9]' then raise exception 'audit_pii_rejected'; end if new.action_code ~ '[0-9]{4}-[0-9]{2}-[0-9]{2}' then raise exception 'audit_pii_rejected'; end if new.metadata::text ~* '(first_name|last_name|address|free_text|message|answer|note|reason_text)' then raise exception 'audit_pii_rejected'; end if new.metadata::text ~ '"[^"]{65,}"' then raise exception 'audit_metadata_value_limit'; end if new.metadata::text ~ '[0-9]{9}' then raise exception 'audit_pii_rejected'; end if new.