create function app.pii_shape_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if new.action_code !~ '^[a-z][a-z0-9_.]{0,95}$' or new.registry_version !~ '^[a-zA-Z0-9_.-]{1,100}$' then raise exception 'audit_codes_only'; end if;
 if jsonb_typeof(new.metadata)<>'object' or length(new.metadata::text)>4096 then raise exception 'audit_ids_only'; end if;
 if exists(select 1 from jsonb_each(new.metadata) e where e.key !~ '^[a-z_]+_(id|code)$' or jsonb_typeof(e.value)<>'string' or (e.key like '%_id' and trim(both '"' from e.value::text) !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$') or (e.key like '%_code' and trim(both '"' from e.value::text) !~ '^[a-z][a-z0-9_]{0,63}$') or e.key in ('name_code','email_code','phone_code','dob_code')) then raise exception 'audit_ids_only'; end if;
 if new.simulated and new.outcome<>'simulated' then raise exception 'simulated_outcome_required'; end if;
 return new;
end $$;
create trigger audit_pii before insert on public.audit_events for each row execute function app.pii_shape_guard();
/* Replaced invalid draft synthetic guard below with concise JSON-shape dispatch.
create function app.synthetic_guard() returns trigger language plpgsql set search_path='' as $$ begin if new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='patient_contacts' and not exists(select 1 from public.patients where id=new.patient_id and org_id=new.org_id and synthetic) then raise exception 'beta_synthetic_patient_required'; end if tg_table_name='accounts' and tg_op='UPDATE' and new.kind<>old.kind then raise exception 'account_kind_immutable'; end if tg_table_name='patients' and new.dob>=current_date then raise exception 'dob_must_be_past'; end if tg_table_name='consent_records' and (jsonb_typeof(new.recipients)<>'array' or jsonb_array_length(new.recipients)=0) then raise exception 'consent_recipients_required'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and (new.expires_at is not null or new.expires_on_event is not null) then raise exception 'standard_tpo_no_expiry'; end if tg_table_name='consent_records' and new.signature_method='verbal_assent' and (new.consent_type not in ('sms_reminder','portal_reminder','referrer_authorization') or (new.consent_type='referrer_authorization' and new.purpose_code<>'enrolled_update')) then raise exception 'verbal_assent_not_allowed'; end if tg_table_name='consent_records' and new.consent_type in ('part2_tpo_single','part2_specific_written','counseling_notes_release','legal_part2_disclosure','advocate_release') and exists(select 1 from unnest(array['patientName','recipients','amountAndKind','purpose','rightToRevoke','expiration','signatureAndDate','redisclosureNotice']) k where new.part2_elements->>k is distinct from 'true') then raise exception 'part2_elements_required'; end if tg_table_name='consent_records' and new.expires_at is not null and new.expires_at<=new.effective_at then raise exception 'consent_expiry_after_effective'; end if tg_table_name='consent_records' and new.purpose_code not in ('treatment','tpo','care_coordination','status_updates','enrolled_update','referral_for_treatment','reentry_coordination','telehealth','group_confidentiality','ai_recording') then raise exception 'unknown_purpose_code'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.items && array['counseling_notes','legal_proceedings','criminal_justice'] then raise exception 'separate_consent_required'; end if tg_table_name='consent_records' and new.signed_at>now()+interval '1 minute' then raise exception 'future_signature'; end if tg_table_name='consent_records' and new.signed_by_kind='paper' and new.signature_method<>'wet_sign_upload' then raise exception 'paper_signature_required'; end if tg_table_name='consent_records' and new.signed_by_kind='patient' and new.signature_method<>'e_sign' then raise exception 'patient_e_sign_required'; end if tg_table_name='consent_records' and tg_op='UPDATE' and (to_jsonb(new)-array['status','updated_at','expiry_event_occurred_at'])<>(to_jsonb(old)-array['status','updated_at','expiry_event_occurred_at']) then raise exception 'signed_consent_content_immutable'; end if tg_table_name='consent_records' and tg_op='UPDATE' and old.status<>'active' then raise exception 'consent_terminal_state'; end if tg_table_name='consent_records' and new.supersedes_id=new.id then raise exception 'consent_supersession_cycle'; end if tg_table_name='consent_records' and new.supersedes_id is not null and not exists(select 1 from public.consent_records r where r.id=new.supersedes_id and r.org_id=new.org_id and r.patient_id=new.patient_id and r.consent_type=new.consent_type and r.recipients=new.recipients) then raise exception 'consent_supersession_scope'; end if tg_table_name='consent_signed_copies' and new.storage_pointer !~ '^consent-signed/[a-f0-9-]+/[a-f0-9-]+/[a-zA-Z0-9_.-]+$' then raise exception 'private_consent_pointer_required'; end if tg_table_name='consent_records' and new.consent_type='part2_specific_written' and coalesce(array_length(new.items,1),0)=0 then raise exception 'specific_items_required'; end if tg_table_name='consent_records' and tg_op='UPDATE' and new.status='active' then raise exception 'consent_status_transition_required'; end if tg_table_name='consent_records' and new.signed_by_kind='patient' and new.consent_type not in ('telehealth','group_confidentiality','part2_tpo_single') then raise exception 'self_sign_scope_denied'; end if tg_table_name='consent_records' and new.signed_by_kind='patient' and new.consent_type='part2_tpo_single' and new.purpose_code<>'tpo' then raise exception 'self_sign_tpo_only'; end if tg_table_name='consent_records' and new.signed_by_kind='patient' and new.consent_type='part2_tpo_single' and not exists(select 1 from public.consent_versions v where v.id=new.version_id and v.org_id=new.org_id and v.form_key='part2_standard') then raise exception 'standard_form_required'; end if tg_table_name='consent_records' and new.version_id is not null and not exists(select 1 from public.consent_versions where id=new.version_id and org_id=new.org_id and published) then raise exception 'published_version_required'; end if tg_table_name='tester_attestations' and new.statement_version<>'fictional-only-v1' then raise exception 'unknown_attestation'; end if tg_table_name='staff_members' and new.account_id is not null and not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and kind='staff' and synthetic) then raise exception 'staff_account_required'; end if tg_table_name='patients' and new.account_id is not null and not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and kind='patient' and synthetic) then raise exception 'patient_account_required'; end if tg_table_name='consent_signed_copies' and not exists(select 1 from public.consent_records where id=new.consent_record_id and org_id=new.org_id and synthetic) then raise exception 'synthetic_consent_required'; end if tg_table_name='consent_records' and not exists(select 1 from public.patients where id=new.patient_id and org_id=new.org_id and synthetic) then raise exception 'synthetic_patient_required'; end if tg_table_name='tester_attestations' and not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and synthetic) then raise exception 'synthetic_account_required'; end if tg_table_name='orgs' and new.org_id<>new.id then raise exception 'org_self_required'; end if tg_table_name='accounts' and tg_op='UPDATE' and new.auth_user_id is distinct from old.auth_user_id then raise exception 'account_identity_immutable'; end if tg_table_name='patients' and tg_op='UPDATE' and new.account_id is distinct from old.account_id then raise exception 'patient_account_link_immutable'; end if tg_table_name='staff_members' and tg_op='UPDATE' and new.account_id is distinct from old.account_id then raise exception 'staff_account_link_immutable'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and exists(select 1 from jsonb_array_elements(new.recipients) r where r->>'kind'='person') then raise exception 'standard_tpo_class_recipients_required'; end if tg_table_name='consent_signed_copies' and new.storage_pointer not like 'consent-signed/'||new.org_id::text||'/'||new.consent_record_id::text||'/%' then raise exception 'consent_pointer_scope'; end if tg_table_name='consent_signed_copies' and not exists(select 1 from public.consent_records r join public.consent_versions v on v.id=r.version_id and v.org_id=r.org_id where r.id=new.consent_record_id and r.org_id=new.org_id) then raise exception 'versioned_signed_copy_required'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and exists(select 1 from jsonb_array_elements(new.recipients) r where coalesce(r->>'directoryRef','') not in ('adelante-program','treating-providers','payers','hie','program-operations')) then raise exception 'standard_tpo_class_recipient_scope'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and new.items && array['advocate_roi','named_recipient','probation_parole'] then raise exception 'separate_consent_required'; end if tg_table_name='consent_records' and jsonb_typeof(new.part2_elements)<>'object' then raise exception 'part2_elements_object_required'; end if tg_table_name='consent_records' and new.effective_at<new.signed_at then raise exception 'consent_effective_before_signature'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and not exists(select 1 from jsonb_array_elements(new.recipients) r where r->>'directoryRef'='adelante-program') then raise exception 'standard_tpo_program_required'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and exists(select 1 from jsonb_array_elements(new.recipients) r where r->>'kind' not in ('org','class')) then raise exception 'standard_tpo_class_recipients_required'; end if tg_table_name='consent_records' and jsonb_array_length(new.recipients)>32 then raise exception 'consent_recipient_limit'; end if tg_table_name='consent_records' and coalesce(array_length(new.items,1),0)>64 then raise exception 'consent_item_limit'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and new.expires_at is not null then raise exception 'standard_tpo_no_expiry'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and new.expires_on_event is not null then raise exception 'standard_tpo_no_expiry'; end if tg_table_name='consent_records' and new.signed_at is null then raise exception 'consent_signature_required'; end if tg_table_name='consent_records' and new.signature_method is null then raise exception 'consent_signature_required'; end if tg_table_name='consent_records' and new.signed_by_kind is null then raise exception 'consent_signer_kind_required'; end if tg_table_name='consent_records' and new.status is null then raise exception 'consent_status_required'; end if tg_table_name='consent_records' and new.purpose_code is null then raise exception 'consent_purpose_required'; end if tg_table_name='consent_records' and new.consent_type is null then raise exception 'typed_consent_required'; end if tg_table_name='consent_records' and new.patient_id is null then raise exception 'consent_patient_required'; end if tg_table_name='consent_records' and new.org_id is null then raise exception 'consent_org_required'; end if tg_table_name='consent_records' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='patients' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='patient_contacts' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='accounts' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='staff_members' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='tester_attestations' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='consent_signed_copies' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='orgs' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='sites' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='locations' and new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if tg_table_name='consent_records' and new.consent_type='part2_tpo_single' and new.purpose_code='tpo' and new.expiry_event_occurred_at is not null and new.status='active' then raise exception 'standard_tpo_no_expiry_event'; end if tg_table_name='consent_records' and new.consent_type='part2_specific_written' and new.items is null then raise exception 'specific_items_required'; end if tg_table_name='consent_records' and new.consent_type in ('counseling_notes_release','legal_part2_disclosure','po_voluntary_coordination') and new.purpose_code='tpo' then raise exception 'separate_purpose_required'; end if tg_table_name='consent_records' and new.consent_type='advocate_release' and new.purpose_code='tpo' then raise exception 'separate_purpose_required'; end if tg_table_name='consent_records' and new.consent_type='part2_specific_written' and new.purpose_code='tpo' then raise exception 'separate_purpose_required'; end if tg_table_name='consent_records' and new.consent_type='telehealth' and new.purpose_code<>'telehealth' then raise exception 'telehealth_purpose_required'; end if tg_table_name='consent_records' and new.consent_type='group_confidentiality' and new.purpose_code<>'group_confidentiality' then raise exception 'group_purpose_required'; end if tg_table_name='consent_records' and new.consent_type='ai_recording' and new.purpose_code<>'ai_recording' then raise exception 'recording_purpose_required'; end if tg_table_name='consent_records' and new.supersedes_id is not null and tg_op='INSERT' then update public.consent_records set status='superseded' where id=new.supersedes_id and org_id=new.org_id and status='active'; end if; return new; end $$;
*/
create function app.synthetic_guard() returns trigger language plpgsql set search_path='' as $$
declare j jsonb:=to_jsonb(new); oldj jsonb; k text;
begin
 if new.synthetic is distinct from true then raise exception 'beta_synthetic_only'; end if;
 if tg_table_name='orgs' then if new.org_id<>new.id then raise exception 'org_self_required'; end if; end if;
 if tg_table_name='patients' then
  if new.dob>=current_date then raise exception 'dob_must_be_past'; end if;
  if new.account_id is not null and not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and kind='patient') then raise exception 'patient_account_required'; end if;
 end if;
 if tg_table_name='staff_members' then if new.account_id is not null and not exists(select 1 from public.accounts where id=new.account_id and org_id=new.org_id and kind='staff') then raise exception 'staff_account_required'; end if; end if;
 if tg_table_name='consent_records' then
  if jsonb_typeof(new.recipients)<>'array' or jsonb_array_length(new.recipients)=0 then raise exception 'consent_recipients_required'; end if;
  if new.purpose_code not in ('treatment','tpo','care_coordination','status_updates','enrolled_update','referral_for_treatment','reentry_coordination','telehealth','group_confidentiality','ai_recording') then raise exception 'unknown_purpose_code'; end if;
  if new.signature_method='verbal_assent' and not (new.consent_type in ('sms_reminder','portal_reminder') or (new.consent_type='referrer_authorization' and new.purpose_code='enrolled_update')) then raise exception 'verbal_assent_not_allowed'; end if;
  if new.consent_type in ('part2_tpo_single','part2_specific_written','counseling_notes_release','legal_part2_disclosure','advocate_release') then
   foreach k in array array['patientName','recipients','amountAndKind','purpose','rightToRevoke','expiration','signatureAndDate','redisclosureNotice'] loop if new.part2_elements->>k is distinct from 'true' then raise exception 'part2_elements_required'; end if; end loop;
  end if;
  if new.expires_at is not null and new.expires_at<=new.effective_at then raise exception 'consent_expiry_after_effective'; end if;
  if new.consent_type='part2_specific_written' and coalesce(array_length(new.items,1),0)=0 then raise exception 'specific_items_required'; end if;
  if new.consent_type='part2_tpo_single' and new.purpose_code='tpo' then
   if new.expires_at is not null or new.expires_on_event is not null then raise exception 'standard_tpo_no_expiry'; end if;
   if new.items && array['counseling_notes','legal_proceedings','criminal_justice','advocate_roi','named_recipient','probation_parole'] then raise exception 'separate_consent_required'; end if;
   if exists(select 1 from jsonb_array_elements(new.recipients) r where coalesce(r->>'directoryRef','') not in ('adelante-program','treating-providers','payers','hie','program-operations') or coalesce(r->>'kind','') not in ('org','class')) then raise exception 'standard_tpo_class_recipients_required'; end if;
  end if;
  if tg_op='UPDATE' then
   oldj:=to_jsonb(old);
   if (j-array['status','updated_at','expiry_event_occurred_at'])<>(oldj-array['status','updated_at','expiry_event_occurred_at']) then raise exception 'signed_consent_content_immutable'; end if;
   if old.status<>'active' or new.status='active' then raise exception 'consent_terminal_state'; end if;
  end if;
  if new.supersedes_id is not null then
   if new.supersedes_id=new.id or not exists(select 1 from public.consent_records r where r.id=new.supersedes_id and r.org_id=new.org_id and r.patient_id=new.patient_id and r.consent_type=new.consent_type and r.recipients=new.recipients) then raise exception 'consent_supersession_scope'; end if;
   if tg_op='INSERT' then update public.consent_records set status='superseded' where id=new.supersedes_id and org_id=new.org_id and status='active'; end if;
  end if;
 end if;
 if tg_table_name='consent_signed_copies' then if new.storage_pointer not like 'consent-signed/'||new.org_id::text||'/'||new.consent_record_id::text||'/%' then raise exception 'private_consent_pointer_required'; end if; end if;
 if tg_table_name='tester_attestations' then if new.statement_version<>'fictional-only-v1' then raise exception 'unknown_attestation'; end if; end if;
 return new;
end $$;
create function app.append_audit(p_action text,p_entity uuid default null,p_patient uuid default null,p_outcome text default 'simulated',p_metadata jsonb default '{}',p_simulated boolean default true,p_registry text default 'phase1') returns uuid language plpgsql security definer set search_path='' as $$ declare a uuid:=app.account_id(); o uuid:=app.org_id(); i uuid; begin if a is null then raise exception 'authenticated_account_required'; end if; insert into public.audit_events(org_id,actor_account_id,actor_role,action_code,entity_id,patient_id,outcome,metadata,simulated,registry_version) values(o,a,coalesce(app.current_role(),(select kind from public.accounts where id=a)),p_action,p_entity,p_patient,p_outcome,p_metadata,p_simulated,p_registry) returning id into i; return i; end $$;
create function app.set_acting_role(p_role text) returns text language plpgsql security definer set search_path='' as $$ declare a uuid:=app.account_id(); o uuid:=app.org_id(); begin if a is null then raise exception 'authenticated_account_required'; end if; perform 1 from public.accounts where id=a for update; if not exists(select 1 from public.staff_members m join public.staff_role_assignments r on r.staff_member_id=m.id and r.org_id=m.org_id where m.account_id=a and m.org_id=o and m.active and r.active and r.role=p_role) then raise exception 'role_not_held'; end if; update public.acting_role_sessions set ended_at=now() where account_id=a and ended_at is null; insert into public.acting_role_sessions(org_id,account_id,role) values(o,a,p_role); perform app.append_audit('acting_role.changed',a,null,'simulated',jsonb_build_object('role_code',p_role),true,'roles-oct27-44x18'); return p_role; end $$;
create function app.consent_covers(p_patient uuid,p_type text,p_recipient text default null,p_purpose_code text default null,p_item text default null,p_at timestamptz default now()) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.consent_records r where r.patient_id=p_patient and r.org_id=app.org_id() and r.consent_type=p_type and r.status='active' and not r.legacy_unverified and not r.needs_review_after_merge and r.expiry_event_occurred_at is null and r.effective_at<=p_at and (r.expires_at is null or p_at<=r.expires_at) and (r.signature_method<>'verbal_assent' or p_type in ('sms_reminder','portal_reminder') or (p_type='referrer_authorization' and r.purpose_code='enrolled_update')) and (p_recipient is null or exists(select 1 from jsonb_array_elements(r.recipients) x where lower(coalesce(x->>'directoryRef',''))=lower(trim(p_recipient)) or lower(trim(coalesce(x->>'name','')))=lower(trim(p_recipient)))) and (p_purpose_code is null or r.purpose_code=p_purpose_code) and (p_item is null or r.items is null or p_item=any(r.items))) $$;
create function app.can_access(p_class text,p_patient uuid default null) returns table(level text,reason text) language plpgsql stable security definer set search_path='' as $$ declare r text:=app.current_role(); l text; begin if app.account_id() is null then return query select 'none'::text,'Sign in required'::text; return; end if; if p_patient is not null and not exists(select 1 from public.patients where id=p_patient and org_id=app.org_id()) then return query select 'none'::text,'Record unavailable'::text; return; end if; if r is null then if app.owns_patient(p_patient) and p_class in ('demographics','consent_ledger') then return query select 'read'::text,null::text; else return query select 'none'::text,'Role does not permit access'::text; end if; return; end if; if r='intake_coordinator' and p_class in ('screeners_sud','sud_treatment') then return query select 'none'::text,'42 CFR Part 2 — consent required'::text; return; end if; if r='clinical_coordinator' and p_class='psychotherapy_notes' then if app.consent_covers(p_patient,'counseling_notes_release','adelante-care-coordination','care_coordination') or app.consent_covers(p_patient,'counseling_notes_release','Adelante care coordination team','care_coordination') or app.consent_covers(p_patient,'counseling_notes_release','adelante-program','care_coordination') or app.consent_covers(p_patient,'counseling_notes_release','Adelante','care_coordination') then return query select 'read'::text,null::text; else return query select 'none'::text,'42 CFR Part 2 — separate release required'::text; end if; return; end if; select g.level into l from app.record_class_grants g where g.role=r and g.record_class=p_class; l:=coalesce(l,'none'); if l='consent_gated' then if app.consent_covers(p_patient,'part2_tpo_single','adelante-program','treatment') or app.consent_covers(p_patient,'part2_tpo_single','adelante-program','tpo') or app.consent_covers(p_patient,'part2_tpo_single','Adelante','treatment') or app.consent_covers(p_patient,'part2_tpo_single','Adelante','tpo') then return query select 'read'::text,null::text; else return query select 'none'::text,'42 CFR Part 2 — consent required'::text; end if; else return query select l,case when l='none' then 'Role does not permit access' else null end; end if; end $$;
create function app.record_view(p_patient uuid,p_class text,p_kind text default 'section') returns uuid language plpgsql security definer set search_path='' as $$ declare a uuid:=app.account_id(); o uuid:=app.org_id(); i uuid; begin if a is null or not exists(select 1 from app.can_access(p_class,p_patient) where level in ('read','write','summary')) then raise exception 'record_access_denied'; end if; perform pg_advisory_xact_lock(hashtextextended(a::text||p_patient::text||p_class,0)); select id into i from public.record_access_log where actor_account_id=a and patient_id=p_patient and record_class=p_class and created_at>now()-interval '5 minutes' order by created_at desc limit 1; if i is not null then update public.record_access_log set view_count=view_count+1,last_viewed_at=now() where id=i; else insert into public.record_access_log(org_id,actor_account_id,actor_role,patient_id,record_class,kind) values(o,a,app.current_role(),p_patient,p_class,p_kind) returning id into i; perform app.append_audit('record.viewed',i,p_patient,'simulated',jsonb_build_object('record_class_code',p_class),true,'phase1'); end if; return i; end $$;
create function app.set_feature_flag(p_flag text,p_mode text,p_reason_code text) returns void language plpgsql security definer set search_path='' as $$ begin if app.current_role()<>'sys_admin' or app.current_role() is null then raise exception 'admin_required'; end if; if p_reason_code is null or p_reason_code !~ '^[a-z][a-z0-9_]{0,63}$' then raise exception 'reason_required'; end if; if p_mode not in ('on','off','live') then raise exception 'unknown_flag_mode'; end if; if not exists(select 1 from public.feature_flags where org_id=app.org_id() and flag_id=p_flag) then raise exception 'unknown_flag'; end if; if p_mode='live' and exists(select 1 from public.feature_flags where org_id=app.org_id() and flag_id=p_flag and simulated) then raise exception 'simulated_cannot_go_live'; end if; update public.feature_flags set enabled=p_mode<>'off',mode=p_mode where org_id=app.org_id() and flag_id=p_flag; perform app.append_audit('feature_flag.changed',null,null,'simulated',jsonb_build_object('flag_code',p_flag,'reason_code',p_reason_code),true,'phase1'); end $$;
create function app.attest_beta(p_language text) returns uuid language plpgsql security definer set search_path='' as $$ declare a uuid:=app.account_id(); i uuid; begin if a is null then raise exception 'authenticated_account_required'; end if; if p_language not in ('en','es') then raise exception 'language_required'; end if; perform 1 from public.accounts where id=a for update; select id into i from public.tester_attestations where account_id=a and statement_version='fictional-only-v1'; if i is null then insert into public.tester_attestations(org_id,account_id,language) values(app.org_id(),a,p_language) returning id into i; perform app.append_audit('beta.attested',i,null,'simulated',jsonb_build_object('statement_code','fictional_only_v1','language_code',p_language),true,'phase1'); end if; return i; end $$;
create policy own_account on public.accounts for select to authenticated using(id=app.account_id());
create policy own_staff on public.staff_members for select to authenticated using(account_id=app.account_id() or (org_id=app.org_id() and app.current_role() in ('sys_admin','clinical_coordinator')));
create policy own_roles on public.staff_role_assignments for select to authenticated using(org_id=app.org_id() and (staff_member_id in (select id from public.staff_members where account_id=app.account_id()) or app.current_role()='sys_admin'));
create policy own_session on public.acting_role_sessions for select to authenticated using(account_id=app.account_id() and org_id=app.org_id());
create policy signed_in_grants on app.record_class_grants for select to authenticated using(app.account_id() is not null);
create policy own_attestation on public.tester_attestations for select to authenticated using(account_id=app.account_id() and org_id=app.org_id());
create policy own_patient on public.patients for select to authenticated using(org_id=app.org_id() and app.owns_patient(id));
create policy own_contacts on public.patient_contacts for select to authenticated using(org_id=app.org_id() and app.owns_patient(patient_id));
create policy own_consents on public.consent_records for select to authenticated using(org_id=app.org_id() and app.owns_patient(patient_id));
create policy own_signed_copies on public.consent_signed_copies for select to authenticated using(org_id=app.org_id() and exists(select 1 from public.consent_records r where r.id=consent_record_id and app.owns_patient(r.patient_id)));
create policy published_versions on public.consent_versions for select to authenticated using(org_id=app.org_id() and published and app.account_id() is not null);
create policy org_flags on public.feature_flags for select to authenticated using(org_id=app.org_id() and app.current_role()='sys_admin');
create policy admin_audit on public.audit_events for select to authenticated using(org_id=app.org_id() and app.current_role()='sys_admin');
create policy compliance_access on public.record_access_log for select to authenticated using(org_id=app.org_id() and app.current_role() in ('sys_admin','credentialing_coordinator'));
create policy own_disclosures on public.disclosure_events for select to authenticated using(org_id=app.org_id() and (app.owns_patient(patient_id) or app.current_role()='sys_admin'));
do $$ declare t text; begin foreach t in array array['orgs','sites','locations','programs','county_programs'] loop execute format('create policy org_reference on public.%I for select to authenticated using (org_id=app.org_id() and app.current_role() is not null)',t); end loop; foreach t in array array['orgs','sites','locations','programs','county_programs','accounts','staff_members','staff_role_assignments','acting_role_sessions','feature_flags','record_access_log','patients','patient_contacts','consent_records'] loop execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()',t); end loop; foreach t in array array['audit_events','consent_versions','consent_signed_copies','disclosure_events','tester_attestations'] loop execute format('create trigger immutable_record before update or delete on public.%I for each row execute function app.immutable_row()',t); end loop; foreach t in array array['orgs','sites','locations','accounts','staff_members','patients','patient_contacts','consent_records','consent_signed_copies','tester_attestations'] loop execute format('create trigger synthetic_only before insert or update on public.%I for each row execute function app.synthetic_guard()',t); end loop; end $$;
create trigger grants_timestamp before update on app.record_class_grants for each row execute function app.touch_updated_at();
revoke all on all functions in schema app from public,anon,authenticated;
grant execute on function app.account_id(),app.org_id(),app.current_role(),app.owns_patient(uuid),app.can_access(text,uuid) to authenticated,service_role;
grant execute on all functions in schema app to service_role;
-- Public wrappers preserve app schema privacy; mutations require a trusted server-only service caller.
create function public.foundation_current_context() returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('account_id',app.account_id(),'org_id',app.org_id(),'role',app.current_role(),'kind',(select kind from public.accounts where id=app.account_id()),'attested',exists(select 1 from public.tester_attestations where account_id=app.account_id() and statement_version='fictional-only-v1')) $$;
revoke all on function public.foundation_current_context() from public,anon; grant execute on function public.foundation_current_context() to authenticated,service_role;
create function public.foundation_set_acting_role(p_role text) returns text language sql security definer set search_path='' as $$ select app.set_acting_role(p_role) $$;
create function public.foundation_attest_beta(p_language text) returns uuid language sql security definer set search_path='' as $$ select app.attest_beta(p_language) $$;
revoke all on function public.foundation_set_acting_role(text),public.foundation_attest_beta(text) from public,anon,authenticated; grant execute on function public.foundation_set_acting_role(text),public.foundation_attest_beta(text) to service_role;
-- All table writes remain denied to authenticated callers. No organization, patient or account seeds until the audited store seed function is installed.
notify pgrst,'reload schema';